"""Bounded lesson and community images for the native Training browser.

Original lesson covers are packaged resources. Community images are obtained only
from already validated catalog rows, cached by :mod:`thumbnail_cache`, and copied to
the native bridge's fixed local directory by one background worker.
"""
from __future__ import annotations

from collections import OrderedDict
import hashlib
import json
import math
import queue
import re
import stat
import threading
import time
from itertools import islice
from pathlib import Path

from .thumbnail_cache import (
    ThumbnailCache,
    ThumbnailCancelled,
    ThumbnailError,
    _to_png,
)


_ASSETS = Path(__file__).parent / "assets" / "lesson-covers"
_MAX_ART_BYTES = 256 * 1024
_MAX_COMMUNITY = 128
_CACHE_FRESH_SECONDS = 24 * 60 * 60
_MANIFEST = ".browser-images.json"
_MANIFEST_TEMP = re.compile(r"\.{1,2}browser-images\.json\.[0-9]+\.[0-9]+\.tmp")
_FILE = re.compile(r"[0-9a-f]{64}\.jpg")
_OWNED_FILE = re.compile(r"[0-9a-f]{64}\.(?:jpg|png)")
_KEY = re.compile(
    r"(?:workshop:(?:steam_maps|bakkes_maps):[1-9][0-9]{0,9}|"
    r"plugin:[1-9][0-9]{0,9})"
)
_SOURCE_LABELS = {
    "steam_maps": "Steam Workshop",
    "bakkes_maps": "BakkesMaps",
    "bakkes_plugins": "BakkesPlugins",
}
_COVERS = (
    ("power-shots", "power-shots.png", "power-shots.json"),
    ("speed-flip", "speed-flip.png", "speed-flip.json"),
    ("flip-reset", "flip-reset.png", "flip-reset.json"),
    ("dribble-flick", "dribble-flick.png", "dribble-flick.json"),
    ("shot-placement", "shot-placement.png", "shot-placement.json"),
    ("fast-aerial", "fast-aerial.png", "fast-aerial.json"),
    ("aerial-air-roll", "aerial-air-roll.png", "aerial-air-roll.json"),
    ("flight-recovery", "flight-recovery.png", "flight-recovery.json"),
)


def _missing() -> dict:
    return {"status": "missing", "file": "", "credit": ""}


def _plain_file(path: Path) -> bool:
    try:
        info = path.lstat()
    except OSError:
        return False
    return stat.S_ISREG(info.st_mode) and not (
        stat.S_ISLNK(info.st_mode)
        or bool(getattr(info, "st_file_attributes", 0) & 0x400)
    )


def _read_manifest(root: Path) -> dict:
    path = root / _MANIFEST
    try:
        if not _plain_file(path) or path.stat().st_size > 32768:
            raise ValueError
        value = json.loads(path.read_text("utf-8"))
        if type(value) is not dict or value.get("schema_version") != 1:
            raise ValueError
        originals = value.get("originals", [])
        community = value.get("community", {})
        retired = value.get("retired", [])
        if (type(originals) is not list or type(community) is not dict
                or type(retired) is not list or len(originals) > len(_COVERS)
                or len(community) > _MAX_COMMUNITY or len(retired) > _MAX_COMMUNITY):
            raise ValueError
        if any(type(name) is not str or _OWNED_FILE.fullmatch(name) is None
               for name in [*originals, *retired]):
            raise ValueError
        cleaned = {}
        for key, name in community.items():
            if (type(key) is not str or _KEY.fullmatch(key) is None
                    or type(name) is not str or _OWNED_FILE.fullmatch(name) is None):
                raise ValueError
            cleaned[key] = name
        return {"schema_version": 1, "originals": list(dict.fromkeys(originals)),
                "community": cleaned, "retired": list(dict.fromkeys(retired))}
    except (OSError, UnicodeError, ValueError):
        return {"schema_version": 1, "originals": [], "community": {}, "retired": []}


def _clean_manifest_temps(root: Path) -> None:
    """Remove only plain temp files created for this service's manifest."""
    try:
        for path in root.iterdir():
            if (_MANIFEST_TEMP.fullmatch(path.name) is not None
                    and path.parent == root and _plain_file(path)):
                try:
                    path.unlink()
                except OSError:
                    pass
    except OSError:
        pass


def _write_manifest(cache: ThumbnailCache, manifest: dict) -> None:
    _clean_manifest_temps(cache._root())
    payload = json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode("utf-8")
    cache._write_atomic(cache._root() / _MANIFEST, payload)


def _prune_owned(root: Path, before: dict, after: dict) -> None:
    old = (set(before["originals"]) | set(before["community"].values())
           | set(before["retired"]))
    keep = (set(after["originals"]) | set(after["community"].values())
            | set(after["retired"]))
    for name in old - keep:
        path = root / name
        try:
            if path.parent == root and _OWNED_FILE.fullmatch(name) and _plain_file(path):
                path.unlink()
        except OSError:
            pass


def _load_cover(base: Path, lesson_id: str, image_name: str, receipt_name: str) -> bytes:
    image_path, receipt_path = base / image_name, base / receipt_name
    if image_path.is_symlink() or receipt_path.is_symlink():
        raise ValueError
    if image_path.stat().st_size > _MAX_ART_BYTES or receipt_path.stat().st_size > 8192:
        raise ValueError
    raw_receipt = receipt_path.read_bytes()
    if len(raw_receipt) > 8192:
        raise ValueError
    receipt = json.loads(raw_receipt)
    if (type(receipt) is not dict or receipt.get("schema_version") != 1
            or receipt.get("lesson_id") != lesson_id
            or receipt.get("filename") != image_name
            or receipt.get("credit") != "Original illustration"
            or receipt.get("kind") != "original_generated_illustration"
            or receipt.get("is_gameplay_evidence") is not False):
        raise ValueError
    data = image_path.read_bytes()
    if (len(data) > _MAX_ART_BYTES
            or hashlib.sha256(data).hexdigest() != receipt.get("sha256")):
        raise ValueError
    image = _to_png(data)
    if len(image) > _MAX_ART_BYTES:
        raise ValueError
    return image


def _to_native_jpeg(data: bytes) -> bytes:
    """Normalize validated image bytes to the native movie's baseline JPEG boundary."""
    png = _to_png(data)
    try:
        from PySide6.QtCore import QBuffer
        from PySide6.QtGui import QImage
    except Exception as exc:  # pragma: no cover - environment failure
        raise ThumbnailError("image encoding is unavailable") from exc
    image = QImage.fromData(png, "PNG")
    if image.isNull() or not (1 <= image.width() <= 480 and 1 <= image.height() <= 270):
        raise ThumbnailError("preview dimensions are out of bounds")
    output = QBuffer()
    if not output.open(QBuffer.ReadWrite):
        raise ThumbnailError("preview could not be opened for encoding")
    if not image.convertToFormat(QImage.Format_RGB888).save(output, "JPEG", 90):
        raise ThumbnailError("preview could not be encoded as JPEG")
    encoded = bytes(output.data())
    if len(encoded) > 2 * 1024 * 1024 or not _baseline_jpeg(encoded):
        raise ThumbnailError("preview JPEG output was invalid")
    return encoded


def _baseline_jpeg(data: bytes) -> bool:
    """Confirm the Qt derivative uses SOF0 and bounded dimensions."""
    if len(data) < 4 or data[:2] != b"\xff\xd8" or data[-2:] != b"\xff\xd9":
        return False
    position = 2
    saw_sof = False
    while position < len(data) - 2:
        if data[position] != 0xFF:
            return False
        while position < len(data) and data[position] == 0xFF:
            position += 1
        if position >= len(data):
            return False
        marker = data[position]
        position += 1
        if marker == 0xD9:
            return False
        if marker == 0x00 or marker == 0xD8 or 0xD0 <= marker <= 0xD7:
            return False
        if position + 2 > len(data):
            return False
        length = int.from_bytes(data[position:position + 2], "big")
        if length < 2 or position + length > len(data):
            return False
        if marker == 0xDA:
            return saw_sof and length >= 6
        if marker == 0xC0:
            if length < 8:
                return False
            height = int.from_bytes(data[position + 3:position + 5], "big")
            width = int.from_bytes(data[position + 5:position + 7], "big")
            components = data[position + 7]
            if (data[position + 2] != 8 or components not in (1, 3)
                    or length != 8 + 3 * components
                    or not (1 <= width <= 480 and 1 <= height <= 270)):
                return False
            saw_sof = True
        elif marker in {*range(0xC1, 0xC4), *range(0xC5, 0xC8),
                      *range(0xC9, 0xCC), *range(0xCD, 0xD0)}:
            return False
        position += length
    return False


def stage_lesson_images(directory, pack_ids=(), *, assets=None):
    """Stage validated original covers and return canonical browser metadata."""
    pack_keys = []
    for identity in islice(pack_ids, 6):
        if (type(identity) is str and 0 < len(identity) <= 80
                and all(char.isascii() and (char.isalnum() or char in "_-")
                        for char in identity)):
            pack_keys.append("lesson:pack:" + identity)
    keys = {
        "power-shots": ["lesson:power-shots", *pack_keys],
        "speed-flip": ["lesson:speed-flip"],
        "flip-reset": ["lesson:flip-reset"],
        "dribble-flick": ["lesson:dribble-flick"],
        "shot-placement": ["lesson:shot-placement"],
        "fast-aerial": ["lesson:fast-aerial"],
        "aerial-air-roll": ["lesson:aerial-air-roll"],
        "flight-recovery": ["lesson:flight-recovery"],
    }
    images = {key: _missing() for values in keys.values() for key in values}
    base = Path(assets) if assets is not None else _ASSETS
    staged: list[str] = []
    cache = ThumbnailCache(Path(directory) / "bridge" / "thumbnails")
    try:
        for lesson_id, image_name, receipt_name in _COVERS:
            try:
                image = _to_native_jpeg(
                    _load_cover(base, lesson_id, image_name, receipt_name))
            except (OSError, ValueError, UnicodeError, ThumbnailError):
                continue
            digest = hashlib.sha256(image).hexdigest()
            target = cache._root() / (digest + ".jpg")
            if not cache._image_equals(target, image):
                cache._write_atomic(target, image)
            staged.append(target.name)
            value = {"status": "ready", "file": target.name,
                     "credit": "Original illustration"}
            for key in keys[lesson_id]:
                images[key] = dict(value)
        if staged:
            root = cache._root()
            _clean_manifest_temps(root)
            before = _read_manifest(root)
            after = dict(before, originals=list(dict.fromkeys(staged)))
            _write_manifest(cache, after)
            _prune_owned(root, before, after)
    except (OSError, ValueError, UnicodeError, ThumbnailError):
        pass
    return images


def _identity(source, source_id) -> tuple[str, str] | None:
    if (type(source) is not str or source not in _SOURCE_LABELS
            or type(source_id) is not int
            or type(source_id) is bool or not 1 <= source_id <= 9_999_999_999):
        return None
    if source == "bakkes_plugins":
        return f"plugin:{source_id}", source
    return f"workshop:{source}:{source_id}", source


class BrowserImageService:
    """Single-worker community thumbnail lookup/fetch and native staging."""

    def __init__(self, directory, images: dict):
        self.images = images
        self._cache = ThumbnailCache(Path(directory) / "thumbnail-cache")
        self._stage = ThumbnailCache(Path(directory) / "bridge" / "thumbnails")
        self._jobs: queue.Queue = queue.Queue(maxsize=_MAX_COMMUNITY)
        self._results: queue.Queue = queue.Queue(maxsize=_MAX_COMMUNITY)
        self._cancel = threading.Event()
        self._generation = 0
        self._sequence = 0
        self._tokens: OrderedDict[str, int] = OrderedDict()
        self._community: OrderedDict[str, str] = OrderedDict()
        self._ownership = threading.Lock()
        self._published_files = self._ready_files()
        try:
            root = self._stage._root(create=False)
            _clean_manifest_temps(root)
            manifest = _read_manifest(root)
            self._community.update(manifest["community"])
        except ThumbnailError:
            pass
        self._thread = threading.Thread(
            target=self._run, name="browser-thumbnail-cache", daemon=True)
        self._thread.start()

    def _ready_files(self) -> frozenset[str]:
        return frozenset(
            value.get("file") for value in self.images.values()
            if isinstance(value, dict) and value.get("status") == "ready"
            and type(value.get("file")) is str
            and _FILE.fullmatch(value["file"]) is not None
        )

    def _refresh_published_files(self) -> None:
        self._published_files = self._ready_files()

    def set_generation(self, generation: int) -> None:
        if type(generation) is int and generation > self._generation:
            self._generation = generation
            for key, value in tuple(self.images.items()):
                if key in self._tokens and value.get("status") == "loading":
                    self.images[key] = _missing()
            self._refresh_published_files()

    def schedule_page(self, items, generation: int) -> None:
        """Schedule only validated server rows from one successful catalog page."""
        self.set_generation(generation)
        for item in islice(items, _MAX_COMMUNITY):
            if type(item) is not dict:
                continue
            identity = _identity(item.get("source"), item.get("source_id"))
            if identity is None:
                continue
            key, source = identity
            creator = item.get("creator")
            url = item.get("thumbnail_url")
            source_url = item.get("source_url")
            if (type(creator) is not str or not creator.strip()
                    or creator.strip().casefold() == "unknown creator"
                    or type(url) is not str or not url
                    or type(source_url) is not str or not source_url):
                self._track(key)
                self.images[key] = _missing()
                self._refresh_published_files()
                continue
            self._schedule(key, source, item["source_id"], generation,
                           url=url, creator=creator, source_url=source_url, network=True)

    def rehydrate(self, targets) -> None:
        """Look up saved identities locally; this never performs network I/O."""
        for target in islice(targets, _MAX_COMMUNITY):
            if type(target) is not dict:
                continue
            identity = _identity(target.get("source"), target.get("source_id"))
            if identity is None:
                continue
            key, source = identity
            self._schedule(key, source, target["source_id"], self._generation,
                           url="", creator="", source_url="", network=False)

    def _track(self, key: str) -> None:
        self._sequence += 1
        self._tokens[key] = self._sequence
        self._tokens.move_to_end(key)
        while len(self._tokens) > _MAX_COMMUNITY:
            old, _token = self._tokens.popitem(last=False)
            self.images.pop(old, None)
        self._refresh_published_files()

    def _schedule(self, key, source, source_id, generation, **metadata) -> None:
        previous = self.images.get(key)
        self._track(key)
        token = self._tokens[key]
        if not (isinstance(previous, dict) and previous.get("status") == "ready"):
            self.images[key] = {"status": "loading", "file": "", "credit": ""}
            self._refresh_published_files()
        job = dict(key=key, source=source, source_id=source_id,
                   generation=generation, token=token, **metadata)
        try:
            self._jobs.put_nowait(job)
        except queue.Full:
            if self.images.get(key, {}).get("status") != "ready":
                self.images[key] = {"status": "error", "file": "", "credit": ""}
                self._refresh_published_files()

    def _stale(self, job) -> bool:
        return self._cancel.is_set() or (
            job["network"] and job["generation"] != self._generation)

    def _emit(self, job, status, value=None) -> None:
        """Hand one terminal result to the main thread without dropping it.

        The results queue is bounded, so a full queue is backpressure, not a
        reason to lose a terminal state. The worker retries with a short
        timeout and abandons only when the job went stale or the service is
        closing; the UI thread is never blocked here.
        """
        item = (job["generation"], job["token"], job["key"],
                job["source"], job["source_id"], job["network"], status, value)
        while True:
            if self._stale(job):
                return
            try:
                self._results.put(item, timeout=0.05)
                return
            except queue.Full:
                continue

    def _run(self) -> None:
        while not self._cancel.is_set():
            try:
                job = self._jobs.get(timeout=0.1)
            except queue.Empty:
                continue
            if self._stale(job):
                continue
            cached = self._cache.lookup(job["source"], job["source_id"])
            if cached is not None and not self._stale(job):
                try:
                    value = self._stage_result(job["key"], cached)
                    self._emit(job, "ready", value)
                except (OSError, ThumbnailError, ValueError):
                    cached = None
            if cached is not None and (not job["network"] or self._cache_fresh(cached)):
                continue
            if not job["network"]:
                if cached is None and not self._stale(job):
                    self._emit(job, "missing")
                continue
            try:
                result = self._cache.fetch(
                    job["source"], job["source_id"], job["url"],
                    creator=job["creator"], source_url=job["source_url"],
                    cancel=lambda: self._stale(job))
                if self._stale(job):
                    continue
                value = self._stage_result(job["key"], result)
                if not self._stale(job):
                    self._emit(job, "ready", value)
            except ThumbnailCancelled:
                continue
            except (OSError, ThumbnailError, ValueError):
                if not self._stale(job):
                    self._emit(job, "error")

    @staticmethod
    def _cache_fresh(result: dict) -> bool:
        """Age a cache entry by its validated receipt commit time.

        The image file is content-addressed, so an unchanged refresh rewrites
        only the receipt; the receipt's ``finalized`` stamp is therefore the
        only honest freshness signal. Missing, non-finite or future stamps are
        treated as stale so the caller refetches instead of trusting them.
        """
        value = result.get("finalized")
        if type(value) not in (int, float) or type(value) is bool:
            return False
        try:
            finalized = float(value)
        except (OverflowError, TypeError, ValueError):
            return False
        if not math.isfinite(finalized) or finalized < 0.0:
            return False
        age = time.time() - finalized
        return 0 <= age <= _CACHE_FRESH_SECONDS

    def _stage_result(self, key: str, result: dict) -> dict:
        if _identity(result.get("source"), result.get("source_id")) != (
                key, result.get("source")):
            raise ThumbnailError("preview identity changed")
        digest = result.get("sha256")
        if type(digest) is not str or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
            raise ThumbnailError("preview digest is invalid")
        source_path = Path(result["path"])
        if not _plain_file(source_path):
            raise ThumbnailError("preview cache file is unavailable")
        if source_path.stat().st_size > 2 * 1024 * 1024:
            raise ThumbnailError("preview cache file is too large")
        data = source_path.read_bytes()
        if hashlib.sha256(data).hexdigest() != digest:
            raise ThumbnailError("preview cache digest changed")
        data = _to_native_jpeg(data)
        digest = hashlib.sha256(data).hexdigest()
        root = self._stage._root()
        target = root / f"{digest}.jpg"
        if not self._stage._image_equals(target, data):
            self._stage._write_atomic(target, data)
        with self._ownership:
            self._community[key] = target.name
            self._community.move_to_end(key)
            while len(self._community) > _MAX_COMMUNITY:
                self._community.popitem(last=False)
            before = _read_manifest(root)
            community = dict(self._community)
            owned = set(before["originals"]) | set(community.values())
            retired = sorted(self._published_files - owned)[:_MAX_COMMUNITY]
            after = dict(before, community=community, retired=retired)
            _write_manifest(self._stage, after)
            _prune_owned(root, before, after)
        creator = " ".join(result["creator"].split())[:80].rstrip()
        credit = f"Preview: {creator} · {_SOURCE_LABELS[result['source']]}"[:120].rstrip()
        return {"status": "ready", "file": target.name, "credit": credit}

    def poll(self) -> bool:
        """Publish at most 64 terminal results on the caller's main thread."""
        changed = False
        for _ in range(64):
            if not self._ownership.acquire(blocking=False):
                break
            try:
                try:
                    generation, token, key, source, source_id, network, status, value = \
                        self._results.get_nowait()
                except queue.Empty:
                    break
                if (self._cancel.is_set() or (network and generation != self._generation)
                        or self._tokens.get(key) != token
                        or _identity(source, source_id) != (key, source)):
                    continue
                current = self.images.get(key, {})
                if status == "ready":
                    try:
                        root = self._stage._root(create=False)
                    except ThumbnailError:
                        root = None
                    if self._staged_ready(root, value):
                        self.images[key] = value
                        changed = True
                    elif not self._staged_ready(root, current):
                        # The staged file is gone (or the staging root was
                        # removed), so an existing "ready" slot is no longer
                        # honest; report a terminal error instead.
                        self.images[key] = {"status": "error", "file": "", "credit": ""}
                        changed = True
                elif current.get("status") != "ready":
                    self.images[key] = {"status": status, "file": "", "credit": ""}
                    changed = True
                self._published_files = self._ready_files()
            finally:
                self._ownership.release()
        return changed

    @staticmethod
    def _staged_ready(root, value) -> bool:
        """True only for a ready value whose staged file really exists."""
        if root is None or not isinstance(value, dict):
            return False
        name = value.get("file")
        if type(name) is not str or _FILE.fullmatch(name) is None:
            return False
        return _plain_file(root / name)

    def close(self) -> None:
        """Cancel promptly; the daemon worker owns no Qt or game objects."""
        self._generation += 1
        self._cancel.set()
